{
  "info": {
    "title": "UAE Account Information API",
    "description": "## UAE Open Finance Account Information API Specification",
    "version": "v2.1-errata2"
  },
  "servers": [
    {
      "url": "/open-finance/account-information/v2.1"
    }
  ],
  "source_path": "/accounts/{AccountId}/product",
  "operations": {
    "get": {
      "tags": [
        "Product"
      ],
      "summary": "Get Product for an Account",
      "description": "The following permissions are applicable to this resource:\n\n* ReadProduct\n\nRefer to the Permissions and Data Clusters section of the Customer Data page for further information.\n",
      "operationId": "GetAccountsAccountIdProduct",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/AccountId"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        }
      ],
      "responses": {
        "200": {
          "$ref": "#/components/responses/200AccountsAccountIdProductRead"
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "404": {
          "$ref": "#/components/responses/404Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "security": [
        {
          "UserOAuth2Security": [
            "openid",
            "accounts"
          ]
        }
      ]
    }
  }
}

{
  "name": "authorization",
  "in": "header",
  "required": true,
  "description": "An authorization Token as per https://tools.ietf.org/html/rfc6750",
  "schema": {
    "type": "string"
  }
}

{
  "name": "AccountId",
  "in": "path",
  "description": "AccountId",
  "required": true,
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-auth-date",
  "required": false,
  "description": "The time when the User last logged in with the TPP. \nAll dates in the HTTP headers are represented as RFC 7231 Full Dates. An example is below: \nSun, 10 Sep 2017 19:43:31 UTC",
  "schema": {
    "type": "string",
    "pattern": "^(Mon|Tue|Wed|Thu|Fri|Sat|Sun), \\d{2} (Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) \\d{4} \\d{2}:\\d{2}:\\d{2} (GMT|UTC)$"
  }
}

{
  "in": "header",
  "name": "x-fapi-customer-ip-address",
  "required": false,
  "description": "The User's IP address if the User is currently logged in with the TPP.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-fapi-interaction-id",
  "required": false,
  "description": "An RFC4122 UID used as a correlation id.",
  "schema": {
    "type": "string"
  }
}

{
  "in": "header",
  "name": "x-customer-user-agent",
  "description": "Indicates the user-agent that the User is using.",
  "required": false,
  "schema": {
    "type": "string"
  }
}

{
  "description": "Product Read",
  "headers": {
    "x-fapi-interaction-id": {
      "description": "An RFC4122 UID used as a correlation id.",
      "required": true,
      "schema": {
        "type": "string"
      }
    }
  },
  "content": {
    "application/json; charset=utf-8": {
      "schema": {
        "$ref": "#/components/schemas/AEReadProduct1"
      }
    },
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/AEReadProduct1"
      }
    },
    "application/jwt": {
      "schema": {
        "$ref": "#/components/schemas/AEReadProduct1Signed"
      }
    }
  }
}

{
  "description": "Product detail for an Account",
  "type": "object",
  "required": [
    "Data",
    "Links",
    "Meta"
  ],
  "properties": {
    "Data": {
      "type": "object",
      "description": "Primary data for the resource",
      "required": [
        "AccountId",
        "Product"
      ],
      "properties": {
        "AccountId": {
          "$ref": "#/components/schemas/AccountId"
        },
        "Product": {
          "type": "array",
          "items": {
            "$ref": "#/components/schemas/AEProduct"
          }
        }
      },
      "additionalProperties": false
    },
    "Links": {
      "$ref": "#/components/schemas/Links"
    },
    "Meta": {
      "$ref": "#/components/schemas/MetaTotalPages"
    }
  },
  "additionalProperties": false
}

{
  "description": "A unique and immutable identifier produced by the LFI to identify the account resource.This identifier has no meaning to the account owner (User 1).",
  "type": "string",
  "minLength": 1,
  "maxLength": 40
}

{
  "type": "object",
  "description": "Set of elements used to define the product details.",
  "properties": {
    "ShariaStructure": {
      "description": "Provides the Islamic finance contract or structure type applied to a product when it has been confirmed as Sharia-compliant.",
      "type": "string",
      "enum": [
        "Ijara",
        "ServiceIjara",
        "Murabaha",
        "Musharaka",
        "Tawarruq"
      ]
    },
    "Charges": {
      "$ref": "#/components/schemas/AEProductCharges"
    },
    "FinanceRates": {
      "anyOf": [
        {
          "$ref": "#/components/schemas/AEProductFinanceRates"
        },
        {
          "$ref": "#/components/schemas/AEJwe"
        }
      ]
    },
    "DepositRates": {
      "$ref": "#/components/schemas/AEProductDepositRates"
    },
    "IsSecured": {
      "type": "boolean",
      "description": "Indicates if the product is secured by collateral."
    },
    "IsSalaryTransferRequired": {
      "description": "Indicates whether salary transfer is required as part of the product eligibility or approval conditions. Common for salary-assigned lending products.",
      "type": "boolean"
    },
    "Tenor": {
      "description": "Product tenor",
      "type": "object",
      "minProperties": 1,
      "properties": {
        "OriginalTenor": {
          "description": "Original product tenor",
          "allOf": [
            {
              "$ref": "#/components/schemas/AEDuration"
            }
          ]
        },
        "RemainingTenor": {
          "description": "Original product tenor",
          "allOf": [
            {
              "$ref": "#/components/schemas/AEDuration"
            }
          ]
        }
      }
    },
    "AssetBacked": {
      "$ref": "#/components/schemas/AEProductAssetBackedProducts"
    },
    "RewardsBenefits": {
      "$ref": "#/components/schemas/AEProductRewardsBenefitsProperties"
    }
  },
  "additionalProperties": false
}

{
  "description": "Fees and charges applicable to the account or product",
  "type": "array",
  "minItems": 1,
  "items": {
    "description": "Properties of the charges applied",
    "type": "object",
    "required": [
      "Name",
      "Description",
      "Charge"
    ],
    "properties": {
      "Type": {
        "description": "Type of charge.",
        "type": "string",
        "enum": [
          "MonthlyFees",
          "AnnualFees",
          "BalanceFallBelow",
          "Overdraft",
          "DomesticTransaction",
          "ForeignTransaction",
          "ATMWithdrawal",
          "ChequeBook",
          "ReplacementChequeBook",
          "ReturnCheque",
          "CardReplacement",
          "AccountStatement",
          "LetterIssued",
          "AccountClosure",
          "CashAdvance",
          "LatePayment",
          "BalanceTransfer",
          "OverLimit",
          "SalesVoucherCopy",
          "Processing",
          "FinanceCancellation",
          "PartialPayment",
          "EarlySettlement",
          "FinalSettlement",
          "Other"
        ]
      },
      "Name": {
        "type": "string",
        "description": "Name of the charge",
        "minLength": 1,
        "maxLength": 40
      },
      "Description": {
        "description": "Description of the fee, including purpose and applicability",
        "type": "string"
      },
      "Charge": {
        "description": "Array of charge components including amount, currency, and applicable rate",
        "type": "array",
        "items": {
          "$ref": "#/components/schemas/AEProductFinancialCalculationMeasure"
        }
      },
      "Conditions": {
        "description": "Array of conditions that trigger the fee",
        "type": "array",
        "items": {
          "$ref": "#/components/schemas/AEProductConditions"
        }
      },
      "Justification": {
        "description": "Reasoning or business logic behind the imposition of the fee",
        "type": "string"
      },
      "Frequency": {
        "description": "Frequency or trigger logic for the reward or fee, such as monthly if balance < 1000, or periodic  Hibah distribution",
        "type": "string"
      },
      "DonatedToCharity": {
        "description": "Confirmation if the charge will be donated to charity when the product is Sharia compliant",
        "type": "boolean"
      },
      "Notes": {
        "type": "string",
        "description": "Additional notes or clarifications about the rate structure",
        "minLength": 1,
        "maxLength": 500
      },
      "SupplementaryInformation": {
        "description": "Optional object for supplementary metadata, such as Sharia compliance notes or reward history",
        "type": "object"
      }
    },
    "additionalProperties": false
  }
}

{
  "type": "object",
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
    },
    "Rate": {
      "description": "Specifies the percentage rate applied when the charge is calculated as a percentage rather than as a fixed monetary amount.",
      "type": "number",
      "minimum": 0,
      "maximum": 100
    },
    "ApplicationFrequency": {
      "description": "Frequency at which reward, interest, or profit is applied, such as monthly or quarterly,  including Islamic profit distribution",
      "type": "string",
      "enum": [
        "Monthly",
        "Daily"
      ]
    },
    "InterestCalculationMethod": {
      "description": "Method used to calculate interest or profit, such as based on principal or drawdown, including  Islamic calculation methods",
      "type": "string",
      "enum": [
        "PrincipalBalance",
        "OutstandingBalance",
        "InitialDrawdownAmount"
      ]
    },
    "MaximumChargeAmount": {
      "description": "Defines the maximum monetary amount that can be applied when a percentage-based charge calculation would otherwise exceed this limit.",
      "type": "object",
      "required": [
        "Amount",
        "Currency"
      ],
      "properties": {
        "Amount": {
          "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
        },
        "Currency": {
          "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
        }
      },
      "additionalProperties": false
    },
    "Basis": {
      "description": "Confirmation of what the charge is based on and calculated against.",
      "type": "string"
    }
  },
  "additionalProperties": false
}

{
  "type": "object",
  "required": [
    "Amount",
    "Currency"
  ],
  "description": "This is the value of the last direct debit collection from the User 1 account.",
  "properties": {
    "Amount": {
      "$ref": "#/components/schemas/AEActiveCurrencyAndAmount_SimpleType"
    },
    "Currency": {
      "$ref": "#/components/schemas/ActiveOrHistoricCurrencyCode_1"
    }
  },
  "additionalProperties": false
}

{
  "description": "A number of monetary units specified in an active currency where the unit of currency is explicit and compliant with ISO 4217.",
  "type": "string",
  "pattern": "^\\d{1,13}$|^\\d{1,13}\\.\\d{1,5}$"
}

{
  "description": "A 3 character alphabetic code allocated to a currency under an international currency identification scheme, as described in the latest edition of the international standard ISO 4217 'Codes for the representation of currencies and funds'.",
  "type": "string",
  "pattern": "^[A-Z]{3,3}$",
  "example": "AED"
}

{
  "type": "object",
  "required": [
    "Description"
  ],
  "properties": {
    "Field": {
      "description": "Field in the product spec that the condition applies to",
      "type": "string"
    },
    "Operator": {
      "description": "Logical operator used in the condition (e.g., ==, >, <=, !=)",
      "type": "string"
    },
    "Value": {
      "description": "Value used in the condition",
      "type": "string"
    },
    "Description": {
      "description": "Description of the fee, including purpose and applicability",
      "type": "string"
    }
  }
}

{
  "title": "Cleartext Finance Rate Data",
  "oneOf": [
    {
      "$ref": "#/components/schemas/AEProductFixedInterestRateProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductFixedProfitRateProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductVariableInterestRateProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductVariableProfitRateProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductHybridInterestRateProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductHybridProfitRateProperties"
    }
  ],
  "discriminator": {
    "propertyName": "RateType",
    "mapping": {
      "FixedInterest": "#/components/schemas/AEProductFixedInterestRateProperties",
      "FixedProfit": "#/components/schemas/AEProductFixedProfitRateProperties",
      "VariableInterest": "#/components/schemas/AEProductVariableInterestRateProperties",
      "VariableProfit": "#/components/schemas/AEProductVariableProfitRateProperties",
      "HybridInterest": "#/components/schemas/AEProductHybridInterestRateProperties",
      "HybridProfit": "#/components/schemas/AEProductHybridProfitRateProperties"
    }
  }
}

{
  "description": "Properties of a fixed interest rate",
  "type": "object",
  "required": [
    "RateType"
  ],
  "properties": {
    "RateType": {
      "description": "A product that carries a fixed interest rate",
      "type": "string",
      "enum": [
        "FixedInterest"
      ]
    }
  },
  "allOf": [
    {
      "$ref": "#/components/schemas/AEProductFixedRateProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductInterestCalculationMethodProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductFinanceRateProperties"
    }
  ]
}

{
  "description": "Properties of a fixed rate associated with all or part of a product.",
  "type": "object",
  "properties": {
    "Description": {
      "description": "Description of the rate.",
      "type": "string"
    },
    "Rate": {
      "description": "Value of the rate.",
      "type": "number"
    },
    "FixedRateEndDate": {
      "description": "End date for the fixed rate period.",
      "type": "string",
      "format": "date"
    },
    "CalculationFrequency": {
      "$ref": "#/components/schemas/AEProductCalculationFrequency"
    },
    "ApplicationFrequency": {
      "$ref": "#/components/schemas/AEProductApplicationFrequency"
    }
  }
}

{
  "allOf": [
    {
      "description": "Describes how often the interest rate is calculated"
    },
    {
      "$ref": "#/components/schemas/AEProductRateFrequencyCodes"
    }
  ]
}

{
  "type": "string",
  "enum": [
    "Monthly",
    "Daily",
    "Quarterly",
    "Annually"
  ]
}

{
  "allOf": [
    {
      "description": "Describes how often the rate is charged, especially in relation to the conditions or triggers (e.g., monthly, one-off, or on each trigger)"
    },
    {
      "$ref": "#/components/schemas/AEProductRateFrequencyCodes"
    }
  ]
}

{
  "type": "object",
  "properties": {
    "InterestCalculationMethod": {
      "$ref": "#/components/schemas/AEProductInterestCalculationMethod"
    }
  }
}

{
  "description": "Method used to calculate interest or profit, depending on the product type",
  "type": "string",
  "enum": [
    "PrincipalBalance",
    "OutstandingBalance",
    "InitialDrawdownAmount"
  ]
}

{
  "description": "Details of the annual percentage rate",
  "type": "object",
  "minProperties": 1,
  "properties": {
    "AnnualPercentageRate": {
      "description": "The annual percentage rate for the product.",
      "type": "object",
      "minProperties": 1,
      "properties": {
        "StartingFrom": {
          "description": "The starting annual percentage rate."
        },
        "UpTo": {
          "description": "The maximum annual percentage rate.",
          "type": "number"
        },
        "AdditionalInformation": {
          "description": "Additional notes or clarifications about the annual percentage rate.",
          "type": "string"
        }
      }
    },
    "Tiers": {
      "description": "The tiers of the finance profit rate product.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "description": "The tier of the finance profit rate product.",
        "required": [
          "Name",
          "Unit"
        ],
        "properties": {
          "Name": {
            "type": "string",
            "description": "The name of the tier."
          },
          "Unit": {
            "type": "string",
            "enum": [
              "Balance",
              "LTV",
              "Rate"
            ],
            "description": "The unit of the tier."
          },
          "ApplicationMethod": {
            "description": "Specifies whether the tier rate is applied only to the balance within the defined balance band or to the customers entire balance once that tier level is reached.",
            "type": "string",
            "enum": [
              "PerTier",
              "WholeBalance"
            ]
          },
          "BalanceTierDetails": {
            "description": "Required when `Unit` is set to `Balance`. Describes balance tier range values.",
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "properties": {
                "MinimumTierValue": {
                  "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
                },
                "MaximumTierValue": {
                  "$ref": "#/components/schemas/AEActiveOrHistoricCurrencyAndAmount_0"
                },
                "TierRate": {
                  "description": "The tier rate.",
                  "type": "number"
                }
              }
            }
          },
          "LTVTierDetails": {
            "description": "Required when `Unit` is set to `LTV`. Defines the interest rate or profit rate applicable to each Loan-to-Value (LTV) range where different rates apply.",
            "type": "array",
            "minItems": 1,
            "items": {
              "type": "object",
              "minProperties": 1,
              "properties": {
                "LTVStart": {
                  "description": "Start rate for LTV Tier",
                  "type": "number"
                },
                "LTVEnd": {
                  "description": "End rate for LTV Tier",
                  "type": "number"
                },
                "TierRate": {
                  "description": "The tier rate.",
                  "type": "number"
                }
              }
            }
          },
          "RateRange": {
            "description": "Required when `Unit` is set to `Rate`. Defines the minimum and maximum interest rate or profit rate range that a customer may be eligibility for, depending on factors such as their credit score, income, etc.",
            "type": "object",
            "properties": {
              "MinimumRate": {
                "description": "Minimum rate range",
                "type": "number"
              },
              "MaximumRate": {
                "description": "Maximum rate range",
                "type": "number"
              },
              "AdditionalInformation": {
                "description": "Additional information on rate range",
                "type": "string"
              }
            }
          }
        }
      }
    },
    "Conditions": {
      "description": "A set of conditions under which the finance rate applies.",
      "type": "array",
      "items": {
        "$ref": "#/components/schemas/AEProductConditions"
      }
    },
    "Notes": {
      "type": "string",
      "description": "Additional notes or clarifications about the rate structure/charge",
      "minLength": 1,
      "maxLength": 500
    },
    "AdditionalInformation": {
      "type": "array",
      "description": "The additional information of the finance profit rate product.",
      "items": {
        "type": "object",
        "properties": {
          "Type": {
            "type": "string",
            "enum": [
              "Other"
            ],
            "description": "The type of additional information."
          },
          "Description": {
            "type": "string",
            "description": "The description of the additional information."
          }
        }
      }
    }
  }
}

{
  "description": "Properties of a fixed profit rate",
  "type": "object",
  "required": [
    "RateType"
  ],
  "properties": {
    "RateType": {
      "description": "A product that carries a fixed profit rate",
      "type": "string",
      "enum": [
        "FixedProfit"
      ]
    }
  },
  "allOf": [
    {
      "$ref": "#/components/schemas/AEProductFixedRateProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductProfitCalculationMethodProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductFinanceRateProperties"
    }
  ]
}

{
  "type": "object",
  "properties": {
    "ProfitCalculationMethod": {
      "$ref": "#/components/schemas/AEProductInterestCalculationMethod"
    }
  }
}

{
  "description": "Properties of a variable interest rate",
  "type": "object",
  "required": [
    "RateType"
  ],
  "properties": {
    "RateType": {
      "description": "A product that carries a variable interest rate",
      "type": "string",
      "enum": [
        "VariableInterest"
      ]
    }
  },
  "allOf": [
    {
      "$ref": "#/components/schemas/AEProductVariableRateProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductInterestCalculationMethodProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductFinanceRateProperties"
    }
  ]
}

{
  "description": "Properties of a variable rate associated with all or part of a product.",
  "type": "object",
  "properties": {
    "Description": {
      "description": "Description of the rate.",
      "type": "string"
    },
    "Rate": {
      "description": "Value of the rate.",
      "type": "number"
    },
    "BenchMark": {
      "description": "Rate benchmark.",
      "type": "string"
    },
    "BenchMarkRate": {
      "description": "Benchmark rate value.",
      "type": "number"
    },
    "Margin": {
      "description": "Margin added to the base rate to determine the effective rate",
      "type": "number"
    },
    "RateReviewFrequency": {
      "$ref": "#/components/schemas/AEDuration"
    },
    "RateReviewNextDate": {
      "description": "Date for next review of the rate.",
      "type": "string",
      "format": "date"
    },
    "CalculationFrequency": {
      "$ref": "#/components/schemas/AEProductCalculationFrequency"
    },
    "ApplicationFrequency": {
      "$ref": "#/components/schemas/AEProductApplicationFrequency"
    }
  }
}

{
  "description": "Properties of a variable profit rate",
  "type": "object",
  "required": [
    "RateType"
  ],
  "properties": {
    "RateType": {
      "description": "A product that carries a variable profit rate",
      "type": "string",
      "enum": [
        "VariableProfit"
      ]
    }
  },
  "allOf": [
    {
      "$ref": "#/components/schemas/AEProductVariableRateProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductProfitCalculationMethodProperties"
    },
    {
      "$ref": "#/components/schemas/AEProductFinanceRateProperties"
    }
  ]
}

{
  "description": "Properties of an interest rates with a fixed and variable element",
  "type": "object",
  "required": [
    "RateType"
  ],
  "properties": {
    "RateType": {
      "description": "A product that carries an interest rate and has both fixed and variable elements",
      "type": "string",
      "enum": [
        "HybridInterest"
      ]
    },
    "FixedRate": {
      "allOf": [
        {
          "$ref": "#/components/schemas/AEProductFixedRateProperties"
